const input = $input.first()?.json ?? {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const clean = (v, max=200) => typeof v === 'string' ? v.trim().slice(0,max) : '';
const name = clean(body.name,120);
const email = clean(body.email,254).toLowerCase();
const phone = clean(body.phone,40);
const interest = clean(body.interest,160);
const source = clean(body.source,80) || 'website';
const consentRaw = body.contactConsent ?? body.consent;
const contactConsent = consentRaw === true || consentRaw === 'yes' || consentRaw === 'true';
const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const digits = phone.replace(/\D/g,'');
const validPhone = /^[+\d() .-]{7,40}$/.test(phone) && digits.length >= 7 && digits.length <= 15;
const valid = !!name && (validEmail || validPhone);
const contactAllowed = valid && contactConsent;
const dedupeKey = validEmail ? 'email:' + email : validPhone ? 'phone:' + digits : '';
const errors = [];
if (!name) errors.push('name_required');
if (!validEmail && !validPhone) errors.push('valid_email_or_phone_required');
return [{json:{ok:valid,status:valid?'accepted':'rejected',errors,lead:{name,email:validEmail?email:'',phone:validPhone?phone:'',interest,source,contact_consent:contactConsent,contact_allowed:contactAllowed},dedupe_key:dedupeKey,storage_status:'not_persisted',follow_up_status:'not_sent',notice:'Accepted means validated only. This workflow does not write to a CRM/database, perform durable deduplication, or send messages. Only contact people when permission and applicable law allow it.'}}];
